var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
return new {path=s.path,dirty=s.isDirty,playing=UnityEditor.EditorApplication.isPlaying,roots=s.GetRootGameObjects().Select(g=>new{name=g.name,active=g.activeSelf,pos=g.transform.position.ToString(),children=g.transform.childCount}).ToArray(),objects=UnityEngine.Object.FindObjectsOfType<Transform>().Where(t=> t.GetComponent<TowerSlot>()!=null || t.GetComponent<Base>()!=null || t.GetComponent<Unity.AI.Navigation.NavMeshSurface>()!=null || t.name.ToLower().Contains("spawn") || t.GetComponent<Camera>()!=null).Select(t=>new{name=t.name,pos=t.position.ToString(),parent=t.parent==null?"":t.parent.name,components=t.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray()}).ToArray()};
